<script>
// import { listScheme, getScheme, delScheme, addScheme, updateScheme } from "@/api/zdzh/scheme";

export default {
  name: "Scheme",
  data() {
    return {
      // 遮罩层
      loading: true,
      // 选中数组
      ids: [],
      // 非单个禁用
      single: true,
      // 非多个禁用
      multiple: true,
      // 显示搜索条件
      showSearch: true,
      // 总条数
      total: 0,
      // 【请填写功能名称】表格数据
      schemeList: [],
      // 弹出层标题
      title: "",
      // 是否显示弹出层
      open: false,
      // 查询参数
      queryParams: {
        page_size:10,
        page_num:1,
        name:'',
        // pageNum: 1,
        // pageSize: 10,
        // diagnosticName: null,
        // diagnosticDescribe: null,
        // isDefault: null,
        // startValue: null,
        // endValue: null,
        // colorCastWarning: null,
        // colorCastAlarm: null,
        // contrastRatioWarning: null,
        // contrastRatioAlarm: null,
        // crossStriationWarning: null,
        // crossStriationAlarm: null,
        // definitionWarning: null,
        // definitionAlarm: null,
        // freezeWarning: null,
        // freezeAlarm: null,
        // highLuminanceWarning: null,
        // highLuminanceAlarm: null,
        // jitterWarning: null,
        // jitterAlarm: null,
        // lossWarning: null,
        // lossAlarm: null,
        // lowLuminanceWarning: null,
        // lowLuminanceAlarm: null,
        // noiseWarning: null,
        // noiseAlarm: null,
        // occlusionWarning: null,
        // occlusionAlarm: null,
        // rollingStripeWarning: null,
        // rollingStripeAlarm: null,
        // sceneChangeWarning: null,
        // sceneChangeAlarm: null,
        // stripeWarning: null,
        // stripeAlarm: null,
        // transverseWaveWarning: null,
        // transverseWaveAlarm: null,
        // createBy: null,
        // updateDate: null,
        // updateBy: null,
        // delDate: null,
        // delBy: null,
        // delFlag: null
      },
      // 表单参数
      form: {
        diagnosticName: null,
        diagnosticDescribe: null,
        isDefault: null,
        startValue: null,
        endValue: null,
        colorCastWarning: null,
        colorCastAlarm: null,
        contrastRatioWarning: null,
        contrastRatioAlarm: null,
        crossStriationWarning: null,
        crossStriationAlarm: null,
        definitionWarning: null,
        definitionAlarm: null,
        freezeWarning: null,
        freezeAlarm: null,
        highLuminanceWarning: null,
        highLuminanceAlarm: null,
        jitterWarning: null,
        jitterAlarm: null,
        lossWarning: null,
        lossAlarm: null,
        lowLuminanceWarning: null,
        lowLuminanceAlarm: null,
        noiseWarning: null,
        noiseAlarm: null,
        occlusionWarning: null,
        occlusionAlarm: null,
        rollingStripeWarning: null,
        rollingStripeAlarm: null,
        sceneChangeWarning: null,
        sceneChangeAlarm: null,
        stripeWarning: null,
        stripeAlarm: null,
        transverseWaveWarning: null,
        transverseWaveAlarm: null,
        createBy: null,
        updateDate: null,
        updateBy: null,
        delDate: null,
        delBy: null,
        delFlag: null
      },
      // 表单校验
      rules: {
      }
    };
  },
  created() {
    // this.getList();
  },
  methods: {
    /** 查询【请填写功能名称】列表 */
    getList() {
      this.loading = true;
      listScheme(this.queryParams).then(response => {
        console.log(response);
        this.schemeList = response.rows;
        this.total = response.total;
        this.loading = false;
      });
    },
    // 取消按钮
    cancel() {
      this.open = false;
      this.reset();
    },
    // 表单重置
    reset() {
      this.form = {
        id: null,
        diagnosticName: null,
        diagnosticDescribe: null,
        isDefault: null,
        startValue: null,
        endValue: null,
        colorCastWarning: null,
        colorCastAlarm: null,
        contrastRatioWarning: null,
        contrastRatioAlarm: null,
        crossStriationWarning: null,
        crossStriationAlarm: null,
        definitionWarning: null,
        definitionAlarm: null,
        freezeWarning: null,
        freezeAlarm: null,
        highLuminanceWarning: null,
        highLuminanceAlarm: null,
        jitterWarning: null,
        jitterAlarm: null,
        lossWarning: null,
        lossAlarm: null,
        lowLuminanceWarning: null,
        lowLuminanceAlarm: null,
        noiseWarning: null,
        noiseAlarm: null,
        occlusionWarning: null,
        occlusionAlarm: null,
        rollingStripeWarning: null,
        rollingStripeAlarm: null,
        sceneChangeWarning: null,
        sceneChangeAlarm: null,
        stripeWarning: null,
        stripeAlarm: null,
        transverseWaveWarning: null,
        transverseWaveAlarm: null,
        createBy: null,
        updateDate: null,
        updateBy: null,
        delDate: null,
        delBy: null,
        delFlag: null
      };
      this.resetForm("form");
    },
    /** 搜索按钮操作 */
    handleQuery() {
      this.queryParams.page_num = 1;
      this.getList();
    },
    /** 重置按钮操作 */
    resetQuery() {
      this.resetForm("queryForm");
      this.handleQuery();
    },
    // 多选框选中数据
    handleSelectionChange(selection) {
      this.ids = selection.map(item => item.id)
      this.single = selection.length !== 1
      this.multiple = !selection.length
    },
    /** 新增按钮操作 */
    handleAdd() {
      this.reset();
      this.open = true;
      this.title = "添加方案配置";
    },
    /** 修改按钮操作 */
    handleUpdate(row) {
      this.reset();
      const id = row.id || this.ids
      getScheme(id).then(response => {
        this.form = response.data;
        this.open = true;
        this.title = "修改方案配置";
      });
    },
    /** 提交按钮 */
    submitForm() {
      this.$refs["form"].validate(valid => {
        if (valid) {
          if (this.form.id != null) {
            updateScheme(this.form).then(response => {
              this.$modal.msgSuccess("修改成功");
              this.open = false;
              this.getList();
            });
          } else {
            addScheme(this.form).then(response => {
              this.$modal.msgSuccess("新增成功");
              this.open = false;
              this.getList();
            });
          }
        }
      });
    },
    /** 删除按钮操作 */
    handleDelete(row) {
      const ids = row.id || this.ids;
      this.$modal.confirm('是否确认删除编号为"' + ids + '"的数据项？').then(function () {
        return delScheme(ids);
      }).then(() => {
        this.getList();
        this.$modal.msgSuccess("删除成功");
      }).catch(() => { });
    },
    /** 导出按钮操作 */
    handleExport() {
      this.download('riskManage/scheme/export', {
        ...this.queryParams
      }, `scheme_${new Date().getTime()}.xlsx`)
    },
    getValue(row, column, cellValue) {
      if (cellValue != null) {
        return 0 + '~' + cellValue
      }

    },
    getValue1(row, column, cellValue) {
      if (cellValue != null) {
        return cellValue + '~' + 100
      }

    },
    indexMethod(index) {
      return ((this.queryParams.pageNum - 1) * this.queryParams.pageSize + 1) + index
    },

  }
};
</script>

