          this.stripeOptions.splice(res, 1)
        }
        this.stripe = '';
        this.stripeOptions.forEach(v => {
          this.stripe = this.stripe + v + ','
        })
      }
      // transverseWaveOptions:[],//横波干扰
      if (type == 'transverseWave') {
        let res = this.transverseWaveOptions.indexOf(value)
        if (res == (-1)) {
          this.transverseWaveOptions.push(value)
        } else {
          this.transverseWaveOptions.splice(res, 1)
        }
        this.transverseWave = '';
        this.transverseWaveOptions.forEach(v => {
          this.transverseWave = this.transverseWave + v + ','
