      }).catch(rek => {
        console.log(rek);
      })
    },
    handleToVideoHistory() {
      this.$router.push('/spznfx_videoDiagnosisHistory')
    },
    // 点击图片展开函数
    handleOpenImg(data) {
      // 记录上下一页所需参数
      this.pictureArrId = data.id
      this.pictureOpen = true
      this.pictureTitle = data.vcr_name + "_" + data.equipment_name + "_" + data.equipment_ip + "_" + data.diagnosis_type
      this.pictureUrl = data.diagnosis_pic
    },
    handleClosePictureOpen() {
      this.pictureOpen = false
    },
    // 图片查看，上一页
    handleUpImg() {
      // pictureArrId是当前弹窗中所展示图片的ID，可以通过当前ID来查询当前图片的位置，并找到相关联的上下一组图片
      let index = this.MonitorPointList.findIndex(v => v.id == this.pictureArrId)
      if (index == 0) {
        this.$message({
          type: 'success',
          message: '当前是第一条信息！！！'
        })
      } else {
        index -= 1
        this.handleOpenImg(this.MonitorPointList[index])
      }
    },
    // 图片查看，下一页
    handleNextImg() {
      let index = this.MonitorPointList.findIndex(v => v.id == this.pictureArrId)
      if (index == this.MonitorPointList.length - 1) {
        this.$message({
          type: 'success',
          message: '当前是最后一条信息！！！'
        })
      } else {
        index += 1
        this.handleOpenImg(this.MonitorPointList[index])
      }
    },


  }

}
